import sys
from common import *
code_tr = lib_code('migracion/transformar.js')
SHEETS = "{ googleSheetsOAuth2Api: { id: '9nvPMe79q16jZyaU', name: 'Google Sheets account' } }"
ins_res = columnas('res_reservas', {k: "={{ $json." + k + " }}" for k in COLUMNAS['res_reservas']})
ev = {'reserva_codigo': '={{ $json.codigo }}', 'tipo': 'creada', 'origen': 'migracion', 'actor': 'Google Sheets', 'antes': '', 'despues': '={{ JSON.stringify($json) }}',
      'ts': '={{ $now.toMillis() }}', 'avisar': False, 'aviso_estado': 'no_aplica', 'aviso_detalle': '', 'calendario_estado': 'no_aplica'}
ev_vals = ', '.join(f"{J(k)}: {E(v) if isinstance(v, str) and '{{' in v else J(v)}" for k, v in ev.items())
ev_schema = ', '.join(f"{{ id: {J(k)}, displayName: {J(k)}, required: false, defaultMatch: false, display: true, type: {J(COLUMNAS['res_eventos'][k])}, canBeUsedToMatch: true }}" for k in ev)
print(f"""import {{ workflow, node, trigger, sticky, expr }} from '@n8n/workflow-sdk';
const whMig = trigger({{ type: 'n8n-nodes-base.webhook', version: 2.1, config: {{ name: 'Migrar desde Google Sheets', position: [0, 0], parameters: {{ httpMethod: 'POST', path: 'reservas-util-migrar', options: {{}} }} }}, output: [{{}}] }});
const leerCfg = node({{ type: 'n8n-nodes-base.dataTable', version: 1.1, config: {{ name: 'Leer configuración', position: [220, 0], alwaysOutputData: true, parameters: {{ resource: 'row', operation: 'get', dataTableId: {tabla('res_config')}, returnAll: true }} }}, output: [{{ id: 1 }}] }});
const leerHoja = node({{ type: 'n8n-nodes-base.httpRequest', version: 4.3, config: {{ name: 'Leer hoja antigua', position: [440, 0], executeOnce: true, credentials: {SHEETS}, parameters: {{ url: 'https://sheets.googleapis.com/v4/spreadsheets/1v3oEuelpVpMrAQS94QjWmkIgM0YD_duY2YbG6fdFhW8/values:batchGet?ranges=Reservas&valueRenderOption=UNFORMATTED_VALUE', authentication: 'predefinedCredentialType', nodeCredentialType: 'googleSheetsOAuth2Api', options: {{}} }} }}, output: [{{ valueRanges: [] }}] }});
const transformar = node({{ type: 'n8n-nodes-base.code', version: 2, config: {{ name: 'Reservas futuras confirmadas', position: [660, 0], parameters: {{ jsCode: {J(code_tr)} }} }}, output: [{{ clave_idem: 'x' }}] }});
const noExiste = node({{ type: 'n8n-nodes-base.dataTable', version: 1.1, config: {{ name: 'Solo las que aún no están', position: [880, 0], parameters: {{ resource: 'row', operation: 'rowNotExists', dataTableId: {tabla('res_reservas')}, matchType: 'allConditions', filters: {condiciones([('clave_idem', 'eq', '={{ $json.clave_idem }}'), ('estado', 'eq', 'confirmada')])} }} }}, output: [{{ clave_idem: 'x' }}] }});
const guardar = node({{ type: 'n8n-nodes-base.dataTable', version: 1.1, config: {{ name: 'Guardar en res_reservas', position: [1100, 0], parameters: {{ resource: 'row', operation: 'insert', dataTableId: {tabla('res_reservas')}, columns: {ins_res} }} }}, output: [{{ id: 1 }}] }});
const historial = node({{ type: 'n8n-nodes-base.dataTable', version: 1.1, config: {{ name: 'Anotar en historial', position: [1320, 0], parameters: {{ resource: 'row', operation: 'insert', dataTableId: {tabla('res_eventos')}, columns: {{ mappingMode: 'defineBelow', value: {{ {ev_vals} }}, matchingColumns: [], schema: [ {ev_schema} ], attemptToConvertTypes: false, convertFieldsToString: false }} }} }}, output: [{{ id: 1 }}] }});

const whArr = trigger({{ type: 'n8n-nodes-base.webhook', version: 2.1, config: {{ name: 'Preparar puesta en marcha', position: [0, 300], parameters: {{ httpMethod: 'POST', path: 'reservas-util-arranque', options: {{}} }} }}, output: [{{}}] }});
const desactivar = node({{ type: 'n8n-nodes-base.dataTable', version: 1.1, config: {{ name: 'Desactivar personal de PRUEBA', position: [220, 300], alwaysOutputData: true, executeOnce: true, parameters: {{ resource: 'row', operation: 'update', dataTableId: {tabla('res_personal')}, matchType: 'allConditions', filters: {condiciones([('nombre', 'like', 'PRUEBA%')])}, columns: {{ mappingMode: 'defineBelow', value: {{ activo: false, recibe_avisos: false }}, matchingColumns: [], schema: [ {{ id: 'activo', displayName: 'activo', required: false, defaultMatch: false, display: true, type: 'boolean', canBeUsedToMatch: true }}, {{ id: 'recibe_avisos', displayName: 'recibe_avisos', required: false, defaultMatch: false, display: true, type: 'boolean', canBeUsedToMatch: true }} ], attemptToConvertTypes: false, convertFieldsToString: false }} }} }}, output: [{{ id: 1 }}] }});
const phoneId = node({{ type: 'n8n-nodes-base.dataTable', version: 1.1, config: {{ name: 'Fijar phone_number_id de WhatsApp', position: [440, 300], alwaysOutputData: true, executeOnce: true, parameters: {{ resource: 'row', operation: 'update', dataTableId: {tabla('res_config')}, matchType: 'allConditions', filters: {condiciones([('clave', 'eq', 'whatsapp_phone_number_id')])}, columns: {{ mappingMode: 'defineBelow', value: {{ valor: '1316907604845467' }}, matchingColumns: [], schema: [ {{ id: 'valor', displayName: 'valor', required: false, defaultMatch: false, display: true, type: 'string', canBeUsedToMatch: true }} ], attemptToConvertTypes: false, convertFieldsToString: false }} }} }}, output: [{{ id: 1 }}] }});
const nota = sticky('## Utilidades (NO publicar)\\nSe ejecutan a mano desde el editor:\\n- **Migrar desde Google Sheets**: copia a `res_reservas` las reservas futuras confirmadas de la hoja antigua. Se puede repetir sin duplicar (clave teléfono+día/hora). Ejecútalo justo antes y justo después de cambiar al enrutador.\\n- **Preparar puesta en marcha**: desactiva los usuarios de PRUEBA de `res_personal` y fija el phone_number_id de WhatsApp en `res_config`.', [whMig, leerCfg, leerHoja], {{ color: 3 }});
export default workflow('utilidades', 'Reservas · Utilidades (ejecución manual)')
  .add(whMig).to(leerCfg).to(leerHoja).to(transformar).to(noExiste).to(guardar).to(historial)
  .add(whArr).to(desactivar).to(phoneId)
  .add(nota);""")
